var t=[{title:`De belangrijkste varianten`,text:`Bij een split squat blijven je voeten in een gespreide stand staan. Een reverse lunge stapt bij elke herhaling naar achteren, en een voorwaartse of lopende lunge brengt het lichaam in een nieuwe positie. Een step-up tilt je op een stabiel platform, en een split squat met het achterste been verhoogd maakt de oefening zwaarder. De varianten overlappen, maar verschillen in balansvraag en in hoever de knie en heup bewegen. Ze werken allemaal goed naast squats op twee benen en heupscharnieren.`},{title:`Basistechniek`,text:`Neem voor een split squat een stand die breed genoeg is om stevig te staan, zak recht omlaag door de knie en heup beheerst te buigen en kom dan omhoog via het werkende been. Houd je voorste voet plat op de vloer en laat de knie een comfortabel pad volgen. Een lichte voorwaartse helling van de romp kan normaal zijn. De beste staplengte hangt af van je lichaamsverhoudingen en waarvoor je traint.`},{title:`Balans en veiligheid`,text:`Houd je tijdens het leren met één hand vast aan een muur of leuning. Als de oefening een balanstest wordt, verkort dan je stap, verlaag de diepte of gebruik minder gewicht tot het weer beheerst krachtwerk is. Vermijd instabiele boxen en heel hoge stappen. Als de beweging steeds gewrichtspijn geeft, stop dan of kies een andere oefening.`},{title:`De kanten vergelijken`,text:`Begin met je minder zelfverzekerde kant en evenaar het aantal goede herhalingen daarna aan de andere kant. Doe bijvoorbeeld twee sets van zes reverse lunges per been terwijl je steun vasthoudt. Kleine verschillen tussen de kanten betekenen niet dat je geblesseerd bent, en betere controle na verloop van tijd is een goed doel. Ga vooruit door eerst de steun los te laten, dan herhalingen toe te voegen en dan weerstand toe te voegen.`}];var a=[{label:`ACE-oefeningenbibliotheek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`NSCA: basis van veiligheid en krachttraining`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Mayo Clinic: techniek bij krachttraining (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var i={sections:t,sources:a};export{i as default,t as sections,a as sources};